# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIF EŞYALARI VE EĞİTİM ARAÇLARI (فِي صَفِّي)</text>\n  <rect x="20" y="45" width="210" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Eril (Müzekker) Eşyalar</text>\n  <text x="125" y="96" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">كِتَابٌ (Kitap) • دَفْتَرٌ (Defter)</text>\n  <text x="125" y="124" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">قَلَمٌ (Kalem) • مَكْتَبٌ (Masa)</text>\n  <text x="125" y="152" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">مَقْعَدٌ (Sıra) • كُرْسِيٌّ (Sandalye)</text>\n  <text x="125" y="180" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">صَفٌّ (Sınıf) • طَالِبٌ (Erkek Öğrenci)</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" fill="#334155">Sonunda yuvarlak te (ة) bulunmaz.</text>\n\n  <rect x="245" y="45" width="210" height="195" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="350" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Dişil (Müennes) Eşyalar</text>\n  <text x="350" y="96" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">سَبُّورَةٌ (Yazı Tahtası)</text>\n  <text x="350" y="124" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">حَقِيبَةٌ (Çanta) • طَاوِلَةٌ (Masa)</text>\n  <text x="350" y="152" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">مِمْحَاةٌ (Silgi) • مَدْرَسَةٌ (Okul)</text>\n  <text x="350" y="180" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">طَالِبَةٌ (Kız Öğrenci)</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" fill="#334155">Sonunda dişillik işareti (ة / ـة) yer alır.</text>\n\n  <rect x="470" y="45" width="210" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="575" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sınıf Ortamı ve Arkadaşlık</text>\n  <text x="575" y="98" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">فِي الصَّفِّ (Sınıfta)</text>\n  <text x="575" y="126" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">فِي الْمَدْرَسَةِ (Okulda)</text>\n  <text x="575" y="154" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">صَدِيقِي (Erkek arkadaşım)</text>\n  <text x="575" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">صَدِيقَتِي (Kız arkadaşım)</text>\n  <text x="575" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">«اَلْعِلْمُ نَافِعٌ» (İlim faydalıdır.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAKIN İŞARET İSİMLERİ (هٰذَا / هٰذِهِ) VE SORU KALIPLARI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Eril (Müzekker) İçin: هٰذَا (Bu)</text>\n  <text x="180" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">مَا هٰذَا؟ (Bu nedir?)</text>\n  <text x="180" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">• هٰذَا كِتَابٌ. (Bu bir kitaptır.)</text>\n  <text x="180" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">• هٰذَا دَفْتَرٌ. (Bu bir defterdir.)</text>\n  <text x="180" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">هَلْ هٰذَا قَلَمٌ؟ (Bu bir kalem midir?)</text>\n  <text x="180" y="204" text-anchor="middle" font-size="12" fill="#334155">نَعَمْ، هٰذَا قَلَمٌ. (Evet, bu bir kalemdir.)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#475569">لَا، هٰذَا مَقْعَدٌ. (Hayır, bu bir sıradır.)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#db2777" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Dişil (Müennes) İçin: هٰذِهِ (Bu)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#831843">مَا هٰذِهِ؟ (Bu nedir?)</text>\n  <text x="520" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">• هٰذِهِ سَبُّورَةٌ. (Bu bir yazı tahtasıdır.)</text>\n  <text x="520" y="152" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">• هٰذِهِ حَقِيبَةٌ. (Bu bir çantadır.)</text>\n  <text x="520" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">هَلْ هٰذِهِ مِمْحَاةٌ؟ (Bu bir silgi midir?)</text>\n  <text x="520" y="204" text-anchor="middle" font-size="12" fill="#334155">نَعَمْ، هٰذِهِ مِمْحَاةٌ. (Evet, bu bir silgidir.)</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#475569">لَا، هٰذِهِ طَاوِلَةٌ. (Hayır, bu bir masadır.)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SINIF İÇİ EYLEM YÖNERGELERİ VE SESLETİM ÖZELLİKLERİ</text>\n  <rect x="25" y="48" width="320" height="190" rx="8" fill="#fef3c7" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b45309">Eril ve Dişil Emir Kipinde Yönergeler</text>\n  <text x="185" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">اِفْتَحْ (Aç - Eril)  |  اِفْتَحِي (Aç - Dişil)</text>\n  <text x="185" y="130" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">أَغْلِقْ (Kapat - Eril)  |  أَغْلِقِي (Kapat - Dişil)</text>\n  <text x="185" y="158" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">خُذْ (Al - Eril)  |  خُذِي (Al - Dişil)</text>\n  <text x="185" y="186" text-anchor="middle" font-size="12" font-weight="bold" fill="#78350f">أَعْطِ (Ver - Eril)  |  أَعْطِي (Ver - Dişil)</text>\n  <text x="185" y="216" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">أَعْطِنِي / أَعْطِينِي (Bana ver!)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Sesletim: Med, Cezim, Tenvin ve Şedde</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Uzatma (Med): أَوْ - تِي - نَا (كِتَاب - حَقِيبَة)</text>\n  <text x="520" y="132" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Cezim (Sükûn): أَيْ - لَمْ - أَنْ (مَكْتَب - دَفْتَر)</text>\n  <text x="520" y="162" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Tenvin (-ün/-en/-in): أَبٌ - بَيْتًا - طَالِبَةٌ</text>\n  <text x="520" y="192" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">• Şedde (Vurgulu): مَدَّ - شَدَّ - كُلٌّ - سَبُّورَةٌ</text>\n  <text x="520" y="220" text-anchor="middle" font-size="11" fill="#475569">Harflerin kelime içindeki konumlarına göre yazılışı</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
